import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  requireSupabase, uploadProfilePhoto, uploadMachinePhoto, provisionAdminPassword, signedImageUrl,
  rpc, frequencyLabel, startOfWeekISO, localDateISO, clean
} from "../../core.js";
import { Avatar, Badge, CardTitle, Empty, ErrorState, Icon, Loading, Modal } from "../components/UI.jsx";

const deptBlank={id:"",dept_code:"",dept_name:"",sort_order:100,is_active:true,free_text_entry:false,free_text_machine_problem:false,free_text_cause_action:false,require_image:true,required_image_types:["Before","Evidence","After"]};
const groupBlank={id:"",department_id:"",group_code:"",group_name:"",sort_order:100,is_active:true};
const machineBlank={id:"",department_id:"",machine_group_id:"",machine_no:"",machine_name:"",line_id:"",production_line:"",is_active:true,photo_path:""};
const userBlank={id:"",employee_code:"",full_name:"",department_id:"",shift:"A",position:"Technician",role:"technician",username:"",password:"",is_active:true,photo_path:""};
const planBlank={id:"",department_id:"",machine_id:"",title:"",description:"",frequency:"monthly",start_date:localDateISO(),responsible_profile_id:"",std_minutes:60,is_active:true};
const itemBlank=()=>({id:"",item_name:"",item_type:"check",min_value:"",max_value:"",unit:"",is_active:true});
const weeklyBlank=()=>({id:"",week_start:startOfWeekISO(),day_of_week:1,department_id:"",machine_id:"",title:"",details:"",assigned_to:"",status:"planned",note:"",sort_order:0});
const masterBlank=(type="problem")=>({id:"",type,department_code:"MVR",code:"",name:"",category:"",is_active:true,machine_ids:[]});
const pointBlank={id:"",machine_id:"",point_code:"",point_name:"",is_active:true};
const TABS=[
  ["departments","แผนก","admin"],["machines","เครื่องจักร","machine"],["users","จัดการช่าง","user"],["teams","ทีมช่างตามแผนก","team"],
  ["masters","Master ตามเครื่อง","list"],["plans","แผน PM","pm"],["weekly","TPM สัปดาห์","calendar"]
];

function Toggle({checked,onChange,label}){return <label className="switch-row"><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)}/><span className="switch-ui"/><span>{label}</span></label>}
function PanelTitle({title,sub,action}){return <div className="section-title"><div><h2>{title}</h2>{sub&&<p>{sub}</p>}</div>{action}</div>}
function FormMessage({msg}){return msg?<div className={`notice ${msg.includes("เรียบร้อย")?"success":"danger"}`}><Icon name={msg.includes("เรียบร้อย")?"check":"alert"} size={18}/><span>{msg}</span></div>:null}

export default function AdminModule({profile}){
  const [tab,setTab]=useState("teams"),[editor,setEditor]=useState(""),[loading,setLoading]=useState(true),[error,setError]=useState(""),[msg,setMsg]=useState("");
  const [departments,setDepartments]=useState([]),[groups,setGroups]=useState([]),[machines,setMachines]=useState([]),[profiles,setProfiles]=useState([]),[plans,setPlans]=useState([]),[weekly,setWeekly]=useState([]),[lines,setLines]=useState([]);
  const [problems,setProblems]=useState([]),[causes,setCauses]=useState([]),[actions,setActions]=useState([]),[points,setPoints]=useState([]),[machineProblemMap,setMachineProblemMap]=useState([]),[machineCauseMap,setMachineCauseMap]=useState([]),[machineActionMap,setMachineActionMap]=useState([]);
  const [photoUrls,setPhotoUrls]=useState({});
  const [dept,setDept]=useState(deptBlank),[group,setGroup]=useState(groupBlank),[machine,setMachine]=useState(machineBlank),[machinePhoto,setMachinePhoto]=useState(null),[machineDrag,setMachineDrag]=useState(false),[user,setUser]=useState(userBlank),[userPhoto,setUserPhoto]=useState(null);
  const machinePhotoInput=useRef(null);
  const [plan,setPlan]=useState(planBlank),[items,setItems]=useState([itemBlank()]),[weeklyForm,setWeeklyForm]=useState(weeklyBlank());
  const [masterType,setMasterType]=useState("problem"),[master,setMaster]=useState(masterBlank("problem")),[point,setPoint]=useState(pointBlank);
  const [teamDept,setTeamDept]=useState("");

  const deptMap=useMemo(()=>Object.fromEntries(departments.map(x=>[x.id,x])),[departments]);
  const groupMap=useMemo(()=>Object.fromEntries(groups.map(x=>[x.id,x])),[groups]);
  const machineMap=useMemo(()=>Object.fromEntries(machines.map(x=>[x.id,x])),[machines]);
  const lineMap=useMemo(()=>Object.fromEntries(lines.map(x=>[x.id,x])),[lines]);
  const technicians=useMemo(()=>profiles.filter(p=>p.role==="technician"),[profiles]);
  const adminProfiles=useMemo(()=>profiles.filter(p=>p.role==="admin"),[profiles]);
  const activeTeam=useMemo(()=>technicians.filter(p=>!teamDept||p.department_id===teamDept),[technicians,teamDept]);
  const machineOptions=useMemo(()=>machines.filter(m=>!plan.department_id||m.department_id===plan.department_id),[machines,plan.department_id]);
  const techOptions=useMemo(()=>technicians.filter(t=>t.is_active&&(!plan.department_id||t.department_id===plan.department_id)),[technicians,plan.department_id]);
  const weeklyMachineOptions=useMemo(()=>machines.filter(m=>!weeklyForm.department_id||m.department_id===weeklyForm.department_id),[machines,weeklyForm.department_id]);
  const machinePhotoPreview=useMemo(()=>machinePhoto?URL.createObjectURL(machinePhoto):"",[machinePhoto]);
  useEffect(()=>()=>{if(machinePhotoPreview)URL.revokeObjectURL(machinePhotoPreview)},[machinePhotoPreview]);
  const departmentMasterMachines=useMemo(()=>{
    if(!master.department_code)return [];
    const deptId=departments.find(d=>d.dept_code===master.department_code)?.id;
    return machines.filter(m=>m.department_id===deptId&&m.is_active);
  },[master.department_code,departments,machines]);


  async function loadAll(){
    setLoading(true);setError("");
    try{
      const sb=requireSupabase(),week=startOfWeekISO();
      const qs=await Promise.all([
        sb.from("departments").select("id,dept_code,dept_name,sort_order,is_active,free_text_entry,free_text_machine_problem,free_text_cause_action,require_image,required_image_types").order("sort_order"),
        sb.from("machine_groups").select("id,department_id,group_code,group_name,sort_order,is_active").order("sort_order").order("group_name"),
        sb.from("machines").select("id,department_id,machine_group_id,machine_no,machine_name,production_line,line_id,is_active,photo_path").order("machine_no"),
        sb.from("app_profiles").select("id,auth_user_id,employee_code,username,full_name,department_id,shift,position,role,is_active,photo_path").order("full_name"),
        sb.from("pm_plans").select("id,department_id,machine_id,title,description,frequency,start_date,responsible_profile_id,responsible_name_snapshot,std_minutes,is_active,created_at").order("created_at",{ascending:false}),
        sb.from("pm_weekly_tasks").select("*").eq("week_start",week).order("day_of_week").order("sort_order"),
        sb.from("production_lines").select("id,line_code,line_name,is_active").eq("is_active",true).order("line_name"),
        sb.from("problems").select("id,problem_code,problem_name,breakdown_type,department_code,is_active").order("problem_name"),
        sb.from("causes").select("id,cause_code,cause_name,category,department_code,is_active").order("cause_name"),
        sb.from("actions").select("id,action_code,action_name,department_code,is_active").order("action_name"),
        sb.from("area_points").select("id,machine_id,point_code,point_name,is_active").order("point_name"),
        sb.from("machine_problem_map").select("machine_id,problem_id"),sb.from("machine_cause_map").select("machine_id,cause_id"),sb.from("machine_action_map").select("machine_id,action_id")
      ]);
      for(const q of qs)if(q.error)throw q.error;
      const [d,g,m,p,pl,w,l,pr,c,a,pt,mpm,mcm,mam]=qs;
      setDepartments(d.data||[]);setGroups(g.data||[]);setMachines(m.data||[]);setProfiles(p.data||[]);setPlans(pl.data||[]);setWeekly(w.data||[]);setLines(l.data||[]);
      setProblems(pr.data||[]);setCauses(c.data||[]);setActions(a.data||[]);setPoints(pt.data||[]);setMachineProblemMap(mpm.data||[]);setMachineCauseMap(mcm.data||[]);setMachineActionMap(mam.data||[]);
      if(!teamDept&&d.data?.length)setTeamDept(d.data[0].id);
      const paths=[...new Set([...(p.data||[]).map(x=>x.photo_path),...(m.data||[]).map(x=>x.photo_path)].filter(Boolean))],urls={};
      await Promise.all(paths.map(async path=>{urls[path]=await signedImageUrl(path,1200)}));setPhotoUrls(urls);
    }catch(e){setError(e.message||"โหลดข้อมูลผู้ดูแลไม่สำเร็จ")}finally{setLoading(false)}
  }
  useEffect(()=>{loadAll()},[]);

  async function action(fn,success){setMsg("");try{await fn();setMsg(success);await loadAll()}catch(e){setMsg(e.message||"ดำเนินการไม่สำเร็จ")}}

  async function saveDept(e){e.preventDefault();await action(async()=>{
    const payload={dept_code:clean(dept.dept_code).toUpperCase(),dept_name:clean(dept.dept_name),sort_order:Number(dept.sort_order)||100,is_active:dept.is_active,free_text_entry:false,free_text_machine_problem:dept.free_text_machine_problem,free_text_cause_action:dept.free_text_cause_action,require_image:true,required_image_types:["Before","Evidence","After"]};
    const q=dept.id?requireSupabase().from("departments").update(payload).eq("id",dept.id):requireSupabase().from("departments").insert(payload);const {error}=await q;if(error)throw error;setDept(deptBlank);setEditor("");
  },"บันทึกแผนกเรียบร้อย")}

  async function saveGroup(e){e.preventDefault();await action(async()=>{
    const payload={department_id:group.department_id,group_code:clean(group.group_code).toUpperCase(),group_name:clean(group.group_name),sort_order:Number(group.sort_order)||100,is_active:group.is_active};
    const q=group.id?requireSupabase().from("machine_groups").update(payload).eq("id",group.id):requireSupabase().from("machine_groups").insert(payload);const {error}=await q;if(error)throw error;setGroup(groupBlank);setEditor("");
  },"บันทึกกลุ่มเครื่องเรียบร้อย")}

  function chooseMachinePhoto(file){
    if(!file)return;
    if(!file.type?.startsWith("image/")){setMsg("รองรับเฉพาะไฟล์รูปภาพ");return}
    if(file.size>8*1024*1024){setMsg("รูปเครื่องต้องมีขนาดไม่เกิน 8 MB");return}
    setMsg("");setMachinePhoto(file);
  }
  function handleMachineDrop(e){e.preventDefault();e.stopPropagation();setMachineDrag(false);chooseMachinePhoto(e.dataTransfer?.files?.[0])}

  async function saveMachine(e){e.preventDefault();await action(async()=>{
    const sb=requireSupabase();
    const selectedLine=lines.find(l=>l.id===machine.line_id);
    const payload={department_id:machine.department_id,machine_group_id:machine.machine_group_id||null,machine_no:clean(machine.machine_no),machine_name:clean(machine.machine_name),line_id:machine.line_id||null,production_line:selectedLine?.line_name||clean(machine.production_line)||null,is_active:machine.is_active};
    let id=machine.id;
    if(id){const {error}=await sb.from("machines").update(payload).eq("id",id);if(error)throw error}else{const {data,error}=await sb.from("machines").insert(payload).select("id").single();if(error)throw error;id=data.id}
    if(machinePhoto){const path=await uploadMachinePhoto({machineId:id,file:machinePhoto});const {error}=await sb.from("machines").update({photo_path:path}).eq("id",id);if(error)throw error}
    setMachine(machineBlank);setMachinePhoto(null);setEditor("");
  },"บันทึกเครื่องจักรเรียบร้อย")}

  async function saveUser(e){e.preventDefault();await action(async()=>{
    const sb=requireSupabase();
    if(!user.department_id&&user.role==="technician")throw new Error("ช่างต้องระบุแผนก");
    if(user.role==="admin"&&!clean(user.username))throw new Error("Admin ต้องระบุชื่อผู้ใช้");
    if(!user.id&&user.role==="admin"&&String(user.password).length<6)throw new Error("Admin ใหม่ต้องตั้งรหัสผ่านอย่างน้อย 6 ตัวอักษร");
    const payload={employee_code:clean(user.employee_code),full_name:clean(user.full_name),department_id:user.department_id||null,shift:user.role==="technician"?(user.shift||null):null,position:clean(user.position)||null,role:user.role,username:user.role==="admin"?clean(user.username).toLowerCase():null,is_active:user.is_active};
    let id=user.id;
    if(id){const {error}=await sb.from("app_profiles").update(payload).eq("id",id);if(error)throw error}else{const {data,error}=await sb.from("app_profiles").insert(payload).select("id").single();if(error)throw error;id=data.id}
    if(userPhoto){const path=await uploadProfilePhoto({profileId:id,file:userPhoto});const {error}=await sb.from("app_profiles").update({photo_path:path}).eq("id",id);if(error)throw error}
    if(user.role==="admin"&&user.password)await provisionAdminPassword(id,user.password);
    setUser(userBlank);setUserPhoto(null);setEditor("");
  },"บันทึกผู้ใช้งานเรียบร้อย")}

  async function moveTech(id,department_id){await action(async()=>{const {error}=await requireSupabase().from("app_profiles").update({department_id}).eq("id",id);if(error)throw error},"ย้ายช่างไปแผนกใหม่เรียบร้อย")}
  async function toggleTech(id,is_active){await action(async()=>{const {error}=await requireSupabase().from("app_profiles").update({is_active}).eq("id",id);if(error)throw error},is_active?"เปิดใช้งานช่างเรียบร้อย":"ปิดใช้งานช่างเรียบร้อย")}

  function masterRows(){return masterType==="problem"?problems:masterType==="cause"?causes:actions}
  function masterMappings(id){const rows=masterType==="problem"?machineProblemMap:masterType==="cause"?machineCauseMap:machineActionMap;const key=masterType==="problem"?"problem_id":masterType==="cause"?"cause_id":"action_id";return rows.filter(x=>x[key]===id).map(x=>x.machine_id)}
  function editMaster(row){setMaster({id:row.id,type:masterType,department_code:row.department_code||"MVR",code:row.problem_code||row.cause_code||row.action_code||"",name:row.problem_name||row.cause_name||row.action_name||"",category:row.breakdown_type||row.category||"",is_active:row.is_active!==false,machine_ids:masterMappings(row.id)});setEditor("master")}
  async function saveMaster(e){e.preventDefault();await action(async()=>{
    const sb=requireSupabase(),type=masterType;
    if(!master.id){
      const payload=type==="problem"?{problem_code:clean(master.code)||null,problem_name:clean(master.name),breakdown_type:clean(master.category)||null,department_code:master.department_code}:type==="cause"?{cause_code:clean(master.code)||null,cause_name:clean(master.name),department_code:master.department_code}:{action_code:clean(master.code)||null,action_name:clean(master.name),department_code:master.department_code};
      await rpc("mvr_admin_create_master_item",{p_type:type,p_payload:payload,p_machine_ids:master.machine_ids});
    }else{
      const table=type==="problem"?"problems":type==="cause"?"causes":"actions";
      const payload=type==="problem"?{problem_code:clean(master.code)||null,problem_name:clean(master.name),breakdown_type:clean(master.category)||null,department_code:master.department_code,is_active:master.is_active}:type==="cause"?{cause_code:clean(master.code)||null,cause_name:clean(master.name),category:clean(master.category)||null,department_code:master.department_code,is_active:master.is_active}:{action_code:clean(master.code)||null,action_name:clean(master.name),department_code:master.department_code,is_active:master.is_active};
      const {error}=await sb.from(table).update(payload).eq("id",master.id);if(error)throw error;await rpc("mvr_admin_set_item_machines",{p_type:type,p_item_id:master.id,p_machine_ids:master.machine_ids});
    }
    setMaster(masterBlank(masterType));setEditor("");
  },"บันทึก Master Data เรียบร้อย")}

  async function savePoint(e){e.preventDefault();await action(async()=>{
    const m=machineMap[point.machine_id];if(!m)throw new Error("เลือกเครื่องจักร");
    const payload={machine_id:point.machine_id,point_code:clean(point.point_code)||null,point_name:clean(point.point_name),machine_name:m.machine_name,machine_no:m.machine_no,is_active:point.is_active};
    const q=point.id?requireSupabase().from("area_points").update(payload).eq("id",point.id):requireSupabase().from("area_points").insert(payload);const {error}=await q;if(error)throw error;setPoint(pointBlank);setEditor("");
  },"บันทึกจุดเสียเรียบร้อย")}

  async function editPlanRow(p){setPlan({...planBlank,...p,responsible_profile_id:p.responsible_profile_id||""});const {data,error}=await requireSupabase().from("pm_checklist_items").select("id,item_order,item_name,item_type,min_value,max_value,unit,is_active").eq("plan_id",p.id).eq("is_active",true).order("item_order");if(error){setMsg(error.message);return}setItems(data?.length?data:[itemBlank()]);setEditor("plan")}
  async function savePlan(e){e.preventDefault();await action(async()=>{
    const sb=requireSupabase(),responsible=profiles.find(p=>p.id===plan.responsible_profile_id),payload={department_id:plan.department_id,machine_id:plan.machine_id,title:clean(plan.title),description:clean(plan.description)||null,frequency:plan.frequency,start_date:plan.start_date,responsible_profile_id:plan.responsible_profile_id||null,responsible_name_snapshot:responsible?.full_name||null,std_minutes:Number(plan.std_minutes)||0,is_active:plan.is_active,created_by:profile.id};let id=plan.id;
    if(id){const {error}=await sb.from("pm_plans").update(payload).eq("id",id);if(error)throw error}else{const {data,error}=await sb.from("pm_plans").insert(payload).select("id").single();if(error)throw error;id=data.id}
    const {data:existing,error:xerr}=await sb.from("pm_checklist_items").select("id").eq("plan_id",id);if(xerr)throw xerr;const keep=new Set(items.filter(i=>i.id).map(i=>i.id));const removed=(existing||[]).filter(x=>!keep.has(x.id)).map(x=>x.id);if(removed.length){const {error}=await sb.from("pm_checklist_items").update({is_active:false}).in("id",removed);if(error)throw error}
    for(let i=0;i<items.length;i++){const it=items[i];if(!clean(it.item_name))continue;const row={plan_id:id,item_order:i+1,item_name:clean(it.item_name),item_type:it.item_type,min_value:it.item_type==="measurement"&&it.min_value!==""?Number(it.min_value):null,max_value:it.item_type==="measurement"&&it.max_value!==""?Number(it.max_value):null,unit:it.item_type==="measurement"?clean(it.unit)||null:null,is_active:true};const q=it.id?sb.from("pm_checklist_items").update(row).eq("id",it.id):sb.from("pm_checklist_items").insert(row);const {error}=await q;if(error)throw error}
    setPlan(planBlank);setItems([itemBlank()]);setEditor("");
  },"บันทึกแผน PM และ Checklist เรียบร้อย")}
  async function generate(p){const until=prompt("สร้างตาราง PM ถึงวันที่ (YYYY-MM-DD)",`${new Date().getFullYear()}-12-31`);if(!until)return;await action(()=>rpc("generate_pm_schedule",{p_plan_id:p.id,p_until:until}),"สร้าง PM Schedule เรียบร้อย")}

  async function saveWeekly(e){e.preventDefault();await action(async()=>{
    const m=machineMap[weeklyForm.machine_id],a=profiles.find(p=>p.id===weeklyForm.assigned_to),payload={week_start:weeklyForm.week_start,day_of_week:Number(weeklyForm.day_of_week),department_id:weeklyForm.department_id,machine_id:weeklyForm.machine_id||null,machine_no_snapshot:m?.machine_no||null,machine_name_snapshot:m?.machine_name||null,title:clean(weeklyForm.title),details:clean(weeklyForm.details)||null,assigned_to:weeklyForm.assigned_to||null,assignee_name_snapshot:a?.full_name||null,status:weeklyForm.status,note:clean(weeklyForm.note)||null,sort_order:Number(weeklyForm.sort_order)||0,created_by:profile.id};const q=weeklyForm.id?requireSupabase().from("pm_weekly_tasks").update(payload).eq("id",weeklyForm.id):requireSupabase().from("pm_weekly_tasks").insert(payload);const {error}=await q;if(error)throw error;setWeeklyForm(w=>({...weeklyBlank(),week_start:w.week_start}));setEditor("")
  },"บันทึกงาน TPM รายสัปดาห์เรียบร้อย")}

  function closeEditor(){
    setEditor("");setMachineDrag(false);setMachinePhoto(null);setUserPhoto(null);
  }
  function patchItem(i,k,v){setItems(a=>a.map((x,n)=>n===i?{...x,[k]:v}:x))}
  if(loading)return <Loading text="กำลังโหลดศูนย์ผู้ดูแล…"/>;
  if(error&&!departments.length)return <ErrorState message={error} onRetry={loadAll}/>;

  return <div className="stack admin-settings-root">
    <section className="hero admin-hero compact-admin-hero">
      <div className="hero-kicker">ADMIN CONTROL CENTER</div>
      <h1>ศูนย์ผู้ดูแลระบบ</h1>
      <p>จัดการแผนก เครื่องจักร ทีมช่าง Master Data และแผน PM/TPM จากจุดเดียว</p>
      <div className="hero-meta"><span className="hero-chip">Admin</span><span className="hero-chip mono">{profiles.length} users</span><span className="hero-chip mono">{machines.length} machines</span></div>
    </section>

    <div className="admin-nav-grid modern-admin-nav">{TABS.map(([k,l,icon])=><button key={k} className={`admin-nav-card ${tab===k?"active":""}`} onClick={()=>{setTab(k);setMsg("");setEditor("")}}><span className="admin-nav-icon"><Icon name={icon} size={24}/></span><span>{l}</span><small>{k==="teams"?`${technicians.filter(x=>x.is_active).length} ช่าง Active`:k==="machines"?`${machines.length} เครื่อง`:k==="plans"?`${plans.length} แผน`:"จัดการ"}</small></button>)}</div>
    <FormMessage msg={msg}/>

    {tab==="departments"&&<section className="admin-section-card">
      <PanelTitle title="แผนก" sub="เลือกการ์ดเพื่อแก้ไขโหมดการกรอกของแต่ละแผนก" action={<button className="btn primary" onClick={()=>{setDept(deptBlank);setEditor("department")}}><Icon name="plus" size={15}/>เพิ่มแผนก</button>}/>
      <div className="settings-card-grid department-card-grid">{departments.map(d=><button type="button" className="settings-item-card" key={d.id} onClick={()=>{setDept({...deptBlank,...d,required_image_types:d.required_image_types||[]});setEditor("department")}}>
        <div className="settings-item-head"><div><b>{d.dept_code}</b><span>{d.dept_name}</span></div><Badge value={d.is_active?"normal":"skipped"}>{d.is_active?"Active":"Inactive"}</Badge></div>
        <div className="settings-stats"><span><b>{technicians.filter(t=>t.department_id===d.id).length}</b> ช่าง</span><span><b>{machines.filter(m=>m.department_id===d.id).length}</b> เครื่อง</span></div>
        <div className="settings-mode-row"><span>จุดเสีย / อาการ</span><b>{d.free_text_machine_problem?"กรอกเอง":"ตัวเลือกตามเครื่อง"}</b></div>
        <div className="settings-mode-row"><span>สาเหตุ / วิธีแก้ไข</span><b>{d.free_text_cause_action?"กรอกเอง":"ตัวเลือกตามเครื่อง"}</b></div>
        <span className="settings-edit-hint"><Icon name="edit" size={14}/>แตะเพื่อแก้ไข</span>
      </button>)}</div>
    </section>}

    {tab==="machines"&&<div className="stack admin-settings-sections">
      <section className="admin-section-card"><PanelTitle title="กลุ่มเครื่อง" sub="กลุ่มแรกที่ช่างเลือกใน Repair Wizard" action={<button className="btn primary" onClick={()=>{setGroup(groupBlank);setEditor("group")}}><Icon name="plus" size={15}/>เพิ่มกลุ่ม</button>}/>
        <div className="settings-card-grid">{groups.map(g=><button type="button" className="settings-item-card" key={g.id} onClick={()=>{setGroup({...groupBlank,...g});setEditor("group")}}><div className="settings-item-head"><div><b>{g.group_name}</b><span className="mono">{g.group_code} · {deptMap[g.department_id]?.dept_code||"-"}</span></div><Badge value={g.is_active?"normal":"skipped"}/></div><div className="settings-stats"><span><b>{machines.filter(m=>m.machine_group_id===g.id).length}</b> เครื่อง</span></div><span className="settings-edit-hint"><Icon name="edit" size={14}/>แก้ไขกลุ่ม</span></button>)}</div>
      </section>
      <section className="admin-section-card"><PanelTitle title="เครื่องจักร" sub="รูปเครื่องจะแสดงในหน้าช่างตอนเลือกกลุ่มและ Machine No." action={<button className="btn primary" onClick={()=>{setMachine(machineBlank);setMachinePhoto(null);setEditor("machine")}}><Icon name="plus" size={15}/>เพิ่มเครื่อง</button>}/>
        <div className="settings-card-grid machine-settings-grid">{machines.map(m=><button type="button" className="settings-item-card machine-settings-card" key={m.id} onClick={()=>{setMachine({...machineBlank,...m,line_id:m.line_id||"",machine_group_id:m.machine_group_id||"",photo_path:m.photo_path||""});setMachinePhoto(null);setEditor("machine")}}>{photoUrls[m.photo_path]?<img className="settings-machine-photo" src={photoUrls[m.photo_path]} alt={m.machine_name}/>:<div className="settings-machine-photo empty"><Icon name="machine" size={24}/></div>}<div className="settings-machine-copy"><div className="settings-item-head"><div><b className="mono">{m.machine_no}</b><span>{m.machine_name}</span></div><Badge value={m.is_active?"normal":"skipped"}/></div><div className="settings-stats"><span>{deptMap[m.department_id]?.dept_code||"-"}</span><span>{groupMap[m.machine_group_id]?.group_name||"ไม่มีกลุ่ม"}</span><span>{m.production_line||"ไม่ระบุไลน์"}</span></div><span className="settings-edit-hint"><Icon name="edit" size={14}/>แก้ไขเครื่อง</span></div></button>)}</div>
      </section>
    </div>}

    {tab==="users"&&<section className="admin-section-card"><PanelTitle title="จัดการผู้ใช้งาน" sub="เพิ่มหรือแก้ไข Technician และ Admin ผ่านการ์ด" action={<button className="btn primary" onClick={()=>{setUser(userBlank);setUserPhoto(null);setEditor("user")}}><Icon name="plus" size={15}/>เพิ่มผู้ใช้งาน</button>}/>
      <div className="settings-card-grid user-settings-grid">{profiles.map(p=><button type="button" className="settings-item-card user-settings-card" key={p.id} onClick={()=>{setUser({...userBlank,...p,department_id:p.department_id||"",shift:p.shift||"A",position:p.position||"",username:p.username||"",password:""});setUserPhoto(null);setEditor("user")}}><div className="settings-user-head"><Avatar name={p.full_name} pathUrl={photoUrls[p.photo_path]} size={48}/><div><b>{p.full_name}</b><span className="mono">{p.employee_code}</span></div><Badge value={p.is_active?"normal":"skipped"}>{p.is_active?"Active":"Inactive"}</Badge></div><div className="settings-stats"><span>{p.role}</span><span>{deptMap[p.department_id]?.dept_code||"ADMIN"}</span>{p.shift&&<span>Shift {p.shift}</span>}</div><span className="settings-edit-hint"><Icon name="edit" size={14}/>แก้ไขข้อมูล</span></button>)}</div>
    </section>}

    {tab==="teams"&&<section className="admin-section-card"><PanelTitle title="ทีมช่างตามแผนก" sub="เลือกแผนก แล้วแตะการ์ดช่างเพื่อแก้ไขข้อมูลหรือย้ายแผนก"/>
      <div className="department-filter-pills">{departments.map(d=><button key={d.id} className={teamDept===d.id?"active":""} onClick={()=>setTeamDept(d.id)}><b>{d.dept_code}</b><span>{technicians.filter(t=>t.department_id===d.id).length} คน</span></button>)}</div>
      <div className="settings-card-grid technician-settings-grid">{activeTeam.map(p=><div className="settings-item-card team-settings-card" key={p.id}><button type="button" className="team-card-main" onClick={()=>{setUser({...userBlank,...p,department_id:p.department_id||"",shift:p.shift||"A",position:p.position||"",password:""});setUserPhoto(null);setEditor("user")}}><div className="settings-user-head"><Avatar name={p.full_name} pathUrl={photoUrls[p.photo_path]} size={50}/><div><b>{p.full_name}</b><span className="mono">{p.employee_code}</span></div><Badge value={p.is_active?"normal":"skipped"}>{p.is_active?"Active":"Inactive"}</Badge></div><div className="settings-stats"><span>กะ {p.shift||"-"}</span><span>{p.position||"Technician"}</span><span>{deptMap[p.department_id]?.dept_code||"-"}</span></div></button><div className="team-quick-actions"><button className={p.is_active?"btn danger small":"btn success small"} onClick={()=>toggleTech(p.id,!p.is_active)}>{p.is_active?"ปิดใช้งาน":"เปิดใช้งาน"}</button><button className="btn ghost small" onClick={()=>{setUser({...userBlank,...p,department_id:p.department_id||"",shift:p.shift||"A",position:p.position||"",password:""});setUserPhoto(null);setEditor("user")}}><Icon name="edit" size={14}/>แก้ไข</button></div></div>)}</div>
    </section>}

    {tab==="masters"&&<section className="admin-section-card"><PanelTitle title="Master Data ตามเครื่อง" sub="ถ้าโหมดแผนกเป็นตัวเลือก ช่างจะเห็นเฉพาะรายการที่ผูกกับเครื่องนั้น" action={<button className="btn primary" onClick={()=>{if(masterType==="point"){setPoint(pointBlank);setEditor("point")}else{setMaster(masterBlank(masterType));setEditor("master")}}}><Icon name="plus" size={15}/>เพิ่มรายการ</button>}/>
      <div className="tabs master-tabs modern-master-tabs">{[["point","จุดเสีย"],["problem","Problem"],["cause","Cause"],["action","Action"]].map(([k,l])=><button className={`tab ${masterType===k?"active":""}`} onClick={()=>{setMasterType(k);setMaster(masterBlank(k));setPoint(pointBlank);setEditor("")}} key={k}>{l}</button>)}</div>
      {masterType==="point"?<div className="settings-card-grid master-settings-grid">{points.map(p=><button type="button" className="settings-item-card" key={p.id} onClick={()=>{setPoint({...pointBlank,...p});setEditor("point")}}><div className="settings-item-head"><div><b>{p.point_name}</b><span><span className="mono">{p.point_code||"-"}</span> · {machineMap[p.machine_id]?.machine_no||"-"}</span></div><Badge value={p.is_active?"normal":"skipped"}/></div><span className="settings-edit-hint"><Icon name="edit" size={14}/>แก้ไขจุดเสีย</span></button>)}</div>:<div className="settings-card-grid master-settings-grid">{masterRows().map(r=><button type="button" className="settings-item-card" key={r.id} onClick={()=>editMaster(r)}><div className="settings-item-head"><div><b>{r.problem_name||r.cause_name||r.action_name}</b><span><span className="mono">{r.problem_code||r.cause_code||r.action_code||"-"}</span> · {r.department_code||"MVR"}</span></div><Badge value={r.is_active?"normal":"skipped"}/></div><div className="settings-mode-row"><span>กำหนดเครื่อง</span><b>{masterMappings(r.id).length?`${masterMappings(r.id).length} เครื่อง`:"ยังไม่กำหนด"}</b></div><span className="settings-edit-hint"><Icon name="edit" size={14}/>แก้ไขและผูกเครื่อง</span></button>)}</div>}
    </section>}

    {tab==="plans"&&<section className="admin-section-card"><PanelTitle title="แผน PM" sub="สร้างและแก้ไขแผน PM ผ่านหน้าต่างเดียว ไม่กินพื้นที่หน้าหลัก" action={<button className="btn purple" onClick={()=>{setPlan(planBlank);setItems([itemBlank()]);setEditor("plan")}}><Icon name="plus" size={15}/>สร้างแผน PM</button>}/>
      <div className="settings-card-grid plan-settings-grid">{!plans.length?<Empty title="ยังไม่มีแผน PM"/>:plans.map(p=><div className="settings-item-card" key={p.id}><button type="button" className="settings-card-button" onClick={()=>editPlanRow(p)}><div className="settings-item-head"><div><b>{p.title}</b><span><span className="mono">{machineMap[p.machine_id]?.machine_no||"-"}</span> · {machineMap[p.machine_id]?.machine_name||"-"}</span></div><Badge value={p.is_active?"normal":"skipped"}>{p.is_active?"Active":"Inactive"}</Badge></div><div className="settings-stats"><span>{frequencyLabel(p.frequency)}</span><span>เริ่ม {p.start_date}</span><span>{p.std_minutes||0} นาที</span></div></button><div className="settings-card-actions"><button className="btn ghost small" onClick={()=>editPlanRow(p)}><Icon name="edit" size={14}/>แก้ไข</button><button className="btn soft small" onClick={()=>generate(p)}>Generate Schedule</button></div></div>)}</div>
    </section>}

    {tab==="weekly"&&<section className="admin-section-card"><PanelTitle title="TPM รายสัปดาห์" sub="จัดงานรายสัปดาห์แบบการ์ด และเปิดแก้ไขเป็น Modal" action={<button className="btn primary" onClick={()=>{setWeeklyForm(weeklyBlank());setEditor("weekly")}}><Icon name="plus" size={15}/>เพิ่มงาน TPM</button>}/>
      <div className="settings-card-grid weekly-settings-grid">{!weekly.length?<Empty title="ยังไม่มีงาน TPM สัปดาห์นี้"/>:weekly.map(t=><button type="button" className="settings-item-card" key={t.id} onClick={()=>{setWeeklyForm({...weeklyBlank(),...t,department_id:t.department_id||"",machine_id:t.machine_id||"",assigned_to:t.assigned_to||"",details:t.details||"",note:t.note||""});setEditor("weekly")}}><div className="settings-item-head"><div><b>{t.title}</b><span>วัน {t.day_of_week} · <span className="mono">{t.machine_no_snapshot||"-"}</span> {t.machine_name_snapshot||""}</span></div><Badge value={t.status}/></div><div className="settings-stats"><span>{deptMap[t.department_id]?.dept_code||"-"}</span>{t.assignee_name_snapshot&&<span>{t.assignee_name_snapshot}</span>}</div><span className="settings-edit-hint"><Icon name="edit" size={14}/>แก้ไขงาน</span></button>)}</div>
    </section>}

    {editor==="department"&&<Modal title={dept.id?`แก้ไขแผนก ${dept.dept_code}`:"เพิ่มแผนก"} onClose={closeEditor}><form className="editor-form" onSubmit={saveDept}><CardTitle icon="admin" title="ตั้งค่าแผนก" sub="กำหนดว่าจะใช้ตัวเลือกตามเครื่องหรือให้ช่างกรอกเอง"/><div className="field-grid cols-2"><div className="field"><label>รหัสแผนก</label><input className="input mono" required value={dept.dept_code} onChange={e=>setDept(d=>({...d,dept_code:e.target.value}))}/></div><div className="field"><label>ชื่อแผนก</label><input className="input" required value={dept.dept_name} onChange={e=>setDept(d=>({...d,dept_name:e.target.value}))}/></div><div className="field"><label>ลำดับ</label><input className="input mono" type="number" value={dept.sort_order} onChange={e=>setDept(d=>({...d,sort_order:e.target.value}))}/></div></div><div className="dept-mode-grid"><div className="dept-mode-card"><div className="dept-mode-head"><Icon name="alert" size={22}/><div><b>จุดเสีย + อาการเสีย</b><span>เลือกวิธีกรอกของช่าง</span></div></div><div className="mode-choice"><button type="button" className={!dept.free_text_machine_problem?"active":""} onClick={()=>setDept(d=>({...d,free_text_machine_problem:false,free_text_entry:false}))}><b>ใช้ตัวเลือกตามเครื่อง</b><small>แสดงเฉพาะรายการที่ Admin ผูกให้เครื่อง</small></button><button type="button" className={dept.free_text_machine_problem?"active":""} onClick={()=>setDept(d=>({...d,free_text_machine_problem:true,free_text_entry:false}))}><b>กรอกเอง</b><small>ช่างพิมพ์จุดเสียและอาการเอง</small></button></div></div><div className="dept-mode-card"><div className="dept-mode-head"><Icon name="repair" size={22}/><div><b>สาเหตุ + วิธีแก้ไข</b><span>ตั้งค่าแยกจากกลุ่มแรกได้</span></div></div><div className="mode-choice"><button type="button" className={!dept.free_text_cause_action?"active":""} onClick={()=>setDept(d=>({...d,free_text_cause_action:false,free_text_entry:false}))}><b>ใช้ตัวเลือกตามเครื่อง</b><small>Cause / Action ต้องผูกกับเครื่อง</small></button><button type="button" className={dept.free_text_cause_action?"active":""} onClick={()=>setDept(d=>({...d,free_text_cause_action:true,free_text_entry:false}))}><b>กรอกเอง</b><small>ช่างพิมพ์สาเหตุและวิธีแก้ไขเอง</small></button></div></div></div><Toggle checked={dept.is_active} onChange={v=>setDept(d=>({...d,is_active:v}))} label="เปิดใช้งานแผนก"/><div className="admin-fixed-rule"><span><Icon name="image" size={20}/></span><div><b>บังคับรูปซ่อม 3 รูป</b><p>ก่อนซ่อม · จุดเสีย · หลังซ่อม</p></div></div><div className="modal-form-actions"><button type="button" className="btn ghost" onClick={closeEditor}>ยกเลิก</button><button className="btn primary">บันทึกแผนก</button></div></form></Modal>}

    {editor==="group"&&<Modal title={group.id?"แก้ไขกลุ่มเครื่อง":"เพิ่มกลุ่มเครื่อง"} onClose={closeEditor}><form className="editor-form" onSubmit={saveGroup}><div className="field-grid cols-2"><div className="field"><label>แผนก</label><select className="select" required value={group.department_id} onChange={e=>setGroup(g=>({...g,department_id:e.target.value}))}><option value="">-- เลือก --</option>{departments.map(d=><option key={d.id} value={d.id}>{d.dept_code}</option>)}</select></div><div className="field"><label>Group Code</label><input className="input mono" required value={group.group_code} onChange={e=>setGroup(g=>({...g,group_code:e.target.value}))}/></div><div className="field"><label>ชื่อกลุ่มเครื่อง</label><input className="input" required value={group.group_name} onChange={e=>setGroup(g=>({...g,group_name:e.target.value}))}/></div><div className="field"><label>ลำดับ</label><input className="input mono" type="number" value={group.sort_order} onChange={e=>setGroup(g=>({...g,sort_order:e.target.value}))}/></div></div><Toggle checked={group.is_active} onChange={v=>setGroup(g=>({...g,is_active:v}))} label="เปิดใช้กลุ่มเครื่อง"/><div className="modal-form-actions"><button type="button" className="btn ghost" onClick={closeEditor}>ยกเลิก</button><button className="btn primary">บันทึกกลุ่ม</button></div></form></Modal>}

    {editor==="machine"&&<Modal title={machine.id?`แก้ไข ${machine.machine_no}`:"เพิ่มเครื่องจักร"} onClose={closeEditor}><form className="editor-form" onSubmit={saveMachine}><div className="field-grid cols-2"><div className="field"><label>แผนก</label><select className="select" required value={machine.department_id} onChange={e=>setMachine(m=>({...m,department_id:e.target.value,machine_group_id:""}))}><option value="">-- เลือก --</option>{departments.map(d=><option key={d.id} value={d.id}>{d.dept_code}</option>)}</select></div><div className="field"><label>กลุ่มเครื่อง</label><select className="select" value={machine.machine_group_id} onChange={e=>setMachine(m=>({...m,machine_group_id:e.target.value}))}><option value="">ไม่ระบุ</option>{groups.filter(g=>g.department_id===machine.department_id).map(g=><option key={g.id} value={g.id}>{g.group_name}</option>)}</select></div><div className="field"><label>Machine No.</label><input className="input mono" required value={machine.machine_no} onChange={e=>setMachine(m=>({...m,machine_no:e.target.value}))}/></div><div className="field"><label>ชื่อเครื่อง</label><input className="input" required value={machine.machine_name} onChange={e=>setMachine(m=>({...m,machine_name:e.target.value}))}/></div><div className="field"><label>Production Line</label><select className="select" value={machine.line_id} onChange={e=>setMachine(m=>({...m,line_id:e.target.value}))}><option value="">ไม่ระบุ</option>{lines.map(l=><option key={l.id} value={l.id}>{l.line_name}</option>)}</select></div><div className="field full"><label>รูปเครื่อง</label><div className={`machine-photo-dropzone ${machineDrag?"dragging":""} ${(machinePhotoPreview||photoUrls[machine.photo_path])?"has-image":""}`} role="button" tabIndex="0" onClick={()=>machinePhotoInput.current?.click()} onKeyDown={e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();machinePhotoInput.current?.click()}}} onDragEnter={e=>{e.preventDefault();setMachineDrag(true)}} onDragOver={e=>{e.preventDefault();setMachineDrag(true)}} onDragLeave={e=>{e.preventDefault();setMachineDrag(false)}} onDrop={handleMachineDrop}>{(machinePhotoPreview||photoUrls[machine.photo_path])?<><img src={machinePhotoPreview||photoUrls[machine.photo_path]} alt={machine.machine_name||"รูปเครื่อง"}/><div className="machine-photo-drop-overlay"><Icon name="image" size={24}/><b>{machinePhoto?"รูปใหม่พร้อมบันทึก":"รูปเครื่องปัจจุบัน"}</b><span>ลากรูปใหม่มาวาง หรือแตะเพื่อเปลี่ยน</span></div></>:<div className="machine-photo-drop-empty"><Icon name="image" size={28}/><b>ลากรูปเครื่องมาวางที่นี่</b><span>หรือแตะเพื่อเลือกไฟล์</span><small>JPG / PNG / WEBP · สูงสุด 8 MB</small></div>}<input ref={machinePhotoInput} className="machine-photo-file-input" type="file" accept="image/*" onChange={e=>chooseMachinePhoto(e.target.files?.[0]||null)}/></div>{machinePhoto&&<button type="button" className="btn ghost small" onClick={()=>{setMachinePhoto(null);if(machinePhotoInput.current)machinePhotoInput.current.value=""}}>ยกเลิกรูปใหม่</button>}</div></div><Toggle checked={machine.is_active} onChange={v=>setMachine(m=>({...m,is_active:v}))} label="เปิดใช้งานเครื่อง"/><div className="modal-form-actions"><button type="button" className="btn ghost" onClick={closeEditor}>ยกเลิก</button><button className="btn primary">บันทึกเครื่องจักร</button></div></form></Modal>}

    {editor==="user"&&<Modal title={user.id?`แก้ไข ${user.full_name}`:"เพิ่มผู้ใช้งาน"} onClose={closeEditor}><form className="editor-form" onSubmit={saveUser}><div className="field-grid cols-2"><div className="field"><label>บทบาท</label><select className="select" value={user.role} onChange={e=>setUser(u=>({...u,role:e.target.value}))}><option value="technician">Technician</option><option value="admin">Admin</option></select></div><div className="field"><label>รหัสพนักงาน</label><input className="input mono" required value={user.employee_code} onChange={e=>setUser(u=>({...u,employee_code:e.target.value}))}/></div><div className="field"><label>ชื่อ-นามสกุล</label><input className="input" required value={user.full_name} onChange={e=>setUser(u=>({...u,full_name:e.target.value}))}/></div>{user.role==="technician"&&<><div className="field"><label>แผนก</label><select className="select" required value={user.department_id} onChange={e=>setUser(u=>({...u,department_id:e.target.value}))}><option value="">-- เลือก --</option>{departments.map(d=><option key={d.id} value={d.id}>{d.dept_code}</option>)}</select></div><div className="field"><label>กะ</label><select className="select" value={user.shift} onChange={e=>setUser(u=>({...u,shift:e.target.value}))}><option value="A">A</option><option value="B">B</option><option value="O">O</option></select></div><div className="field"><label>ตำแหน่ง</label><input className="input" value={user.position} onChange={e=>setUser(u=>({...u,position:e.target.value}))}/></div></>}{user.role==="admin"&&<><div className="field"><label>Username</label><input className="input mono" required value={user.username} onChange={e=>setUser(u=>({...u,username:e.target.value}))}/></div><div className="field"><label>{user.id?"Password ใหม่ (เว้นว่างถ้าไม่เปลี่ยน)":"Password"}</label><input className="input" type="password" minLength="6" required={!user.id} value={user.password} onChange={e=>setUser(u=>({...u,password:e.target.value}))}/></div></>}</div><div className="field"><label>รูปโปรไฟล์</label><input className="input" type="file" accept="image/*" onChange={e=>setUserPhoto(e.target.files?.[0]||null)}/></div><Toggle checked={user.is_active} onChange={v=>setUser(u=>({...u,is_active:v}))} label="Active"/><div className="modal-form-actions"><button type="button" className="btn ghost" onClick={closeEditor}>ยกเลิก</button><button className="btn primary">บันทึกผู้ใช้งาน</button></div></form></Modal>}

    {editor==="point"&&<Modal title={point.id?"แก้ไขจุดเสีย":"เพิ่มจุดเสีย"} onClose={closeEditor}><form className="editor-form" onSubmit={savePoint}><div className="field"><label>เครื่องจักร</label><select className="select" required value={point.machine_id} onChange={e=>setPoint(p=>({...p,machine_id:e.target.value}))}><option value="">-- เลือก --</option>{machines.map(m=><option key={m.id} value={m.id}>{deptMap[m.department_id]?.dept_code} · {m.machine_no} · {m.machine_name}</option>)}</select></div><div className="field-grid cols-2"><div className="field"><label>Point Code</label><input className="input mono" value={point.point_code} onChange={e=>setPoint(p=>({...p,point_code:e.target.value}))}/></div><div className="field"><label>ชื่อจุดเสีย</label><input className="input" required value={point.point_name} onChange={e=>setPoint(p=>({...p,point_name:e.target.value}))}/></div></div><Toggle checked={point.is_active} onChange={v=>setPoint(p=>({...p,is_active:v}))} label="Active"/><div className="modal-form-actions"><button type="button" className="btn ghost" onClick={closeEditor}>ยกเลิก</button><button className="btn primary">บันทึกจุดเสีย</button></div></form></Modal>}

    {editor==="master"&&<Modal title={master.id?`แก้ไข ${masterType}`:`เพิ่ม ${masterType}`} onClose={closeEditor}><form className="editor-form" onSubmit={saveMaster}><div className="field-grid cols-2"><div className="field"><label>แผนก</label><select className="select" value={master.department_code} onChange={e=>setMaster(m=>({...m,department_code:e.target.value,machine_ids:[]}))}>{departments.map(d=><option key={d.id} value={d.dept_code}>{d.dept_code}</option>)}</select></div><div className="field"><label>Code</label><input className="input mono" value={master.code} onChange={e=>setMaster(m=>({...m,code:e.target.value}))}/></div><div className="field"><label>ชื่อรายการ</label><input className="input" required value={master.name} onChange={e=>setMaster(m=>({...m,name:e.target.value}))}/></div>{masterType!=="action"&&<div className="field"><label>{masterType==="problem"?"ประเภทงานเสีย":"Category"}</label><input className="input" value={master.category} onChange={e=>setMaster(m=>({...m,category:e.target.value}))}/></div>}</div><div className="field"><label>กำหนดให้เครื่องจักร</label>{!departmentMasterMachines.length?<div className="master-machine-empty"><Icon name="machine" size={22}/><div><b>แผนกนี้ยังไม่มีเครื่องจักร</b><span>เพิ่มเครื่องจักรก่อนแล้วจึงผูกตัวเลือกได้</span></div></div>:<div className="master-machine-grid modal-machine-map-grid">{departmentMasterMachines.map(m=><button type="button" key={m.id} className={`master-machine-chip ${master.machine_ids.includes(m.id)?"active":""}`} onClick={()=>setMaster(x=>({...x,machine_ids:x.machine_ids.includes(m.id)?x.machine_ids.filter(id=>id!==m.id):[...x.machine_ids,m.id]}))}><span className="mono">{m.machine_no}</span><b>{m.machine_name}</b>{master.machine_ids.includes(m.id)&&<Icon name="check" size={15}/>}</button>)}</div>}<div className="help important">ถ้าไม่เลือกเครื่อง รายการนี้จะไม่ปรากฏใน Dropdown ของช่าง</div></div><Toggle checked={master.is_active} onChange={v=>setMaster(m=>({...m,is_active:v}))} label="Active"/><div className="modal-form-actions"><button type="button" className="btn ghost" onClick={closeEditor}>ยกเลิก</button><button className="btn primary">บันทึก Master</button></div></form></Modal>}

    {editor==="plan"&&<Modal title={plan.id?"แก้ไขแผน PM":"สร้างแผน PM"} onClose={closeEditor}><form className="editor-form plan-editor-form" onSubmit={savePlan}><div className="field-grid cols-2"><div className="field"><label>แผนก</label><select className="select" required value={plan.department_id} onChange={e=>setPlan(p=>({...p,department_id:e.target.value,machine_id:"",responsible_profile_id:""}))}><option value="">-- เลือก --</option>{departments.filter(d=>d.is_active).map(d=><option key={d.id} value={d.id}>{d.dept_code}</option>)}</select></div><div className="field"><label>เครื่องจักร</label><select className="select" required value={plan.machine_id} onChange={e=>setPlan(p=>({...p,machine_id:e.target.value}))}><option value="">-- เลือก --</option>{machineOptions.filter(m=>m.is_active).map(m=><option key={m.id} value={m.id}>{m.machine_no} · {m.machine_name}</option>)}</select></div><div className="field"><label>ความถี่</label><select className="select" value={plan.frequency} onChange={e=>setPlan(p=>({...p,frequency:e.target.value}))}>{["daily","weekly","monthly","quarterly","semiannual","annual"].map(f=><option key={f} value={f}>{frequencyLabel(f)}</option>)}</select></div><div className="field"><label>วันเริ่ม</label><input className="input" type="date" value={plan.start_date} onChange={e=>setPlan(p=>({...p,start_date:e.target.value}))}/></div><div className="field"><label>ชื่อแผน</label><input className="input" required value={plan.title} onChange={e=>setPlan(p=>({...p,title:e.target.value}))}/></div><div className="field"><label>เวลามาตรฐาน (นาที)</label><input className="input mono" type="number" min="0" value={plan.std_minutes} onChange={e=>setPlan(p=>({...p,std_minutes:e.target.value}))}/></div><div className="field"><label>ผู้รับผิดชอบ</label><select className="select" value={plan.responsible_profile_id} onChange={e=>setPlan(p=>({...p,responsible_profile_id:e.target.value}))}><option value="">ไม่ระบุ</option>{techOptions.map(t=><option key={t.id} value={t.id}>{t.full_name}</option>)}</select></div><div className="field full"><label>รายละเอียดแผน</label><textarea className="textarea" value={plan.description} onChange={e=>setPlan(p=>({...p,description:e.target.value}))}/></div></div><PanelTitle title="รายการตรวจ" sub="ปกติ / ผิดปกติ / ไม่เกี่ยวข้อง" action={<button type="button" className="btn soft small" onClick={()=>setItems(a=>[...a,itemBlank()])}><Icon name="plus" size={14}/>เพิ่มข้อ</button>}/><div className="stack checklist-modal-list">{items.map((it,i)=><div className="checklist-admin-row modal-checklist-row" key={it.id||i}><div className="item-order mono">{i+1}</div><div className="field"><label>ชื่อรายการ</label><input className="input" value={it.item_name} onChange={e=>patchItem(i,"item_name",e.target.value)}/></div><div className="field"><label>ชนิด</label><select className="select" value={it.item_type} onChange={e=>patchItem(i,"item_type",e.target.value)}><option value="check">ตรวจสภาพ</option><option value="measurement">วัดค่า</option></select></div>{it.item_type==="measurement"&&<><div className="field"><label>Min</label><input className="input mono" type="number" step="any" value={it.min_value??""} onChange={e=>patchItem(i,"min_value",e.target.value)}/></div><div className="field"><label>Max</label><input className="input mono" type="number" step="any" value={it.max_value??""} onChange={e=>patchItem(i,"max_value",e.target.value)}/></div><div className="field"><label>หน่วย</label><input className="input mono" value={it.unit||""} onChange={e=>patchItem(i,"unit",e.target.value)}/></div></>}<button type="button" className="btn ghost small" onClick={()=>setItems(a=>a.filter((_,n)=>n!==i))}>ลบ</button></div>)}</div><Toggle checked={plan.is_active} onChange={v=>setPlan(p=>({...p,is_active:v}))} label="เปิดใช้แผน"/><div className="modal-form-actions"><button type="button" className="btn ghost" onClick={closeEditor}>ยกเลิก</button><button className="btn purple">บันทึกแผนและ Checklist</button></div></form></Modal>}

    {editor==="weekly"&&<Modal title={weeklyForm.id?"แก้ไข TPM สัปดาห์":"เพิ่มงาน TPM รายสัปดาห์"} onClose={closeEditor}><form className="editor-form" onSubmit={saveWeekly}><div className="field-grid cols-2"><div className="field"><label>สัปดาห์เริ่ม</label><input className="input" type="date" value={weeklyForm.week_start} onChange={e=>setWeeklyForm(w=>({...w,week_start:startOfWeekISO(e.target.value)}))}/></div><div className="field"><label>วัน</label><select className="select" value={weeklyForm.day_of_week} onChange={e=>setWeeklyForm(w=>({...w,day_of_week:e.target.value}))}>{["จันทร์","อังคาร","พุธ","พฤหัสบดี","ศุกร์","เสาร์","อาทิตย์"].map((d,i)=><option key={d} value={i+1}>{d}</option>)}</select></div><div className="field"><label>แผนก</label><select className="select" required value={weeklyForm.department_id} onChange={e=>setWeeklyForm(w=>({...w,department_id:e.target.value,machine_id:"",assigned_to:""}))}><option value="">-- เลือก --</option>{departments.map(d=><option key={d.id} value={d.id}>{d.dept_code}</option>)}</select></div><div className="field"><label>เครื่องจักร</label><select className="select" value={weeklyForm.machine_id} onChange={e=>setWeeklyForm(w=>({...w,machine_id:e.target.value}))}><option value="">ไม่ระบุ</option>{weeklyMachineOptions.map(m=><option key={m.id} value={m.id}>{m.machine_no} · {m.machine_name}</option>)}</select></div><div className="field"><label>งาน</label><input className="input" required value={weeklyForm.title} onChange={e=>setWeeklyForm(w=>({...w,title:e.target.value}))}/></div><div className="field"><label>ผู้รับผิดชอบ</label><select className="select" value={weeklyForm.assigned_to} onChange={e=>setWeeklyForm(w=>({...w,assigned_to:e.target.value}))}><option value="">ไม่ระบุ</option>{technicians.filter(p=>p.is_active&&(!weeklyForm.department_id||p.department_id===weeklyForm.department_id)).map(p=><option key={p.id} value={p.id}>{p.full_name}</option>)}</select></div><div className="field full"><label>รายละเอียด</label><textarea className="textarea" value={weeklyForm.details} onChange={e=>setWeeklyForm(w=>({...w,details:e.target.value}))}/></div></div><div className="modal-form-actions"><button type="button" className="btn ghost" onClick={closeEditor}>ยกเลิก</button><button className="btn primary">บันทึกงาน TPM</button></div></form></Modal>}
  </div>;
}
